<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { storeToRefs } from 'pinia';
import { LocalStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import { isObjectEmtpy } from 'src/utils/general';
import helperMixin from 'src/mixins/helperMixin.js';
import { api, getAuthorizationToken } from 'pages/APIs';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import LayoutBuilderBtn from 'src/pages/Settings/LayoutBuilder/EditOrCreateBtn.vue';
import {
  addOrgIdQueryString,
  getOrgId,
} from 'src/utils/organization/org_id_helper';
import {
  useDropdownStore,
  useFormBuilderStore,
  useSettingStore,
  useDocAttributesStore,
} from 'src/store/main';
import ModelTrainingCounter from 'src/pages/Settings/Components/flipCardCounter/ModelTrainingCounter.vue';
import {
  supplierDocTypeKey,
  doc_script_module_setting,
  models_labels_module_setting,
  permission_groups_to_exclude,
  custom_validation_rules_enabled,
  CONSTANTS,
  isDefaultOrg
} from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, displayFieldLabel],
  components: {
    Loader,
    LayoutBuilderBtn,
    ModelTrainingCounter,
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == false && oldVal == true) {
          this.setAutoAccountingSettings();
        }
      },
    },
  },
  data() {
    return {
      doc_script_module_setting,
      models_labels_module_setting,
      permission_groups_to_exclude
    };
  },
  computed: {
    defaultDocTypes(): any[] {
      return Object.values(this.apiData).filter((doc: any) =>
        isDefaultOrg(doc.org_id)
      );
    },
    customDocTypes(): any[] {
      return Object.values(this.apiData).filter((doc: any) =>
        !isDefaultOrg(doc.org_id)
      );
    }
  },
  mounted() {
    this.getDocumentTypes(true);
    this.getTemplatesForDocuments();
    this.getDocTypeAllSettings();

    document.addEventListener('regexes_saved', this.newChangesSavedForRegexes);
  },
  unmounted: function () {
    document.removeEventListener(
      'regexes_saved',
      this.newChangesSavedForRegexes,
    );
  },
  methods: {
    getDocTypeIcon(documentName: string): string {
      const iconMap: { [key: string]: string } = {
        'INVOICE': 'receipt_long',
        'CREDIT_NOTE': 'paid',
        'DELIVERY_NOTE': 'local_shipping',
        'ORDER_CONFIRMATION': 'shopping_bag',
        'CONTRACT': 'article',
        'QUOTE': 'calculate',
        'PURCHASE_ORDER': 'shopping_cart',
        'XML_INVOICE': 'code',
        'FATTURAPA': 'receipt',
        'CUSTOMER_ORDERS': 'list_alt',
        'EXPORT_CERTIFICATE': 'verified',
      };
      return iconMap[documentName] || 'description';
    },

    async getDocumentTypes(showLoader: boolean) {
      let response: any;
      try {
        if (showLoader) {
          this.showLoading();
        }
        let token: string = await getAuthorizationToken();
        response = await axios.get(
          addOrgIdQueryString(api.get_document_types),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw { message: response.data.message };
        }

        // if every thing workes fine remove this commented code.
        // just removed duplicate loop this part is handled in below loop.

        // response.data.data.forEach((row: any, index: any) => {
        //   if (row['document_key']) {
        //     row['label'] = this.displayFieldLabel(row);
        //     this.apiData[row['document_key']] = row;
        //   }
        // });

        if (response.data && response.data.data) {
          this.doc_type_list = [];
          const filterData = response.data.data.filter(
            (doc: any) => !supplierDocTypeKey.includes(doc.document_key),
          );
          filterData.forEach((docObj: any, index: any) => {

            //Skip Supplier M3 Document Type
            if (this.permission_groups_to_exclude.includes(docObj.document_name)) {
              return;
            }
            let docTypeLabel = this.displayFieldLabel(docObj);

            // prepare data to populate list
            if (docObj['document_key']) {
              docObj['auto_accounting'] = !docObj['auto_accounting']
                ? false
                : true;
              docObj['label'] = docTypeLabel;
              docObj['extraction_type_model'] =
                this.setExtractionTypeModel(docObj);
              this.apiData[docObj['document_key']] = docObj;
              this.doc_type_auto_accounting_setting[
                docObj['document_key'] + '_auto_accounting'
              ] = false;
            }

            // prepare Dropdown
            this.doc_type_list.push(
              Object.assign(
                {},
                { value: docObj.document_key, label: docTypeLabel },
              ),
            );
          });
          LocalStorage.set('doc_types', this.doc_type_list);
        }

        this.resetDocTypeRegexData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        if (showLoader) {
          this.hideLoading();
        }
      }
    },

    setAutoAccountingSettings() {
      this.user_settings[this.setting_name] = false;
      for (const [key, value] of Object.entries(
        this.doc_type_auto_accounting_setting,
      )) {
        if (this.user_settings.hasOwnProperty(key)) {
          this.doc_type_auto_accounting_setting[key] = this.user_settings[key];
        }
      }
    },

    setExtractionTypeModel(docObj: any) {
      if (docObj.extraction_type === 'FIX_COORDINATES') {
        return false;
      }

      return true;
    },

    manageSettings(settingName: string) {
      this.$router.push(settingName);
    },
    isManageLayoutsEnabled(row: any): boolean {
      return (
        this.getSettingsByDocTypeAndSettingKey(
          row.document_key,
          CONSTANTS.LAYOUT_SELECTION_RULES_ENABLED,
        ) === true
      );
    },
    // Rule-manager links appear only when the doc type has the feature enabled.
    // Both flags come from the single bulk attribute fetch (getDocTypeAllSettings).
    validationRulesEnabled(row: any): boolean {
      return (
        this.getSettingsByDocTypeAndSettingKey(
          row.document_key,
          custom_validation_rules_enabled,
        ) === true
      );
    },
    transformationRulesEnabled(row: any): boolean {
      return (
        this.getSettingsByDocTypeAndSettingKey(
          row.document_key,
          CONSTANTS.TRANSFORMATION_RULES_ENABLED,
        ) === true
      );
    },
    async showRegexesListView(doc_type: string) {
      if (
        !this.doc_type_regexes ||
        !this.doc_type_regexes[doc_type] ||
        !this.doc_type_regexes[doc_type]['regexes'] ||
        this.doc_type_regexes[doc_type]['regexes']['loading_data']
      ) {
        return;
      }
      let regexes = this.doc_type_regexes[doc_type]['regexes'];
      try {
        if (this.language_origin_list.length === 0) {
          await this.fetchLanguageOptions();
        }

        regexes['loading_data'] = true;
        this.showLoading();
        if (regexes['api_data'] === false) {
          await this.getDocumentTypeRegexes(doc_type);
        }

        regexes['display_list'] = true;

        setTimeout(() => {
          regexes['display_list'] = false;
        }, 0);
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
      } finally {
        regexes['loading_data'] = false;
        this.hideLoading();
      }
    },
    async getDocumentTypeRegexes(doc_type: string) {
      if (!doc_type || doc_type === '') {
        throw { message: 'Document Type is missing' };
      }
      let response: any;
      let token: string = await getAuthorizationToken();

      let formData = new FormData();
      let data = {
        regexType: doc_type,
      };
      formData.append('data', JSON.stringify(data));
      formData.append('org_id', getOrgId());

      response = await axios.post(
        api.post_data_fellowkv + api.get_document_type_regexes,
        formData,
        {
          headers: {
            Authorization: token,
          },
        },
      );

      let regexes = this.doc_type_regexes[doc_type]['regexes'];
      regexes['api_data'] = true;
      regexes['data'] = [];
      if (!response.data) {
        throw { message: 'No Data return from api' };
      }
      if (response.data.hasOwnProperty('message')) {
        throw response.data;
      }

      response.data.forEach((row: any, index: any) => {
        regexes['data'].push(row);
      });
    },
    newChangesSavedForRegexes(e: any) {
      if (!e || !e.detail) {
        return;
      }
      let doc_type = e.detail;
      this.doc_type_regexes[doc_type]['regexes']['api_data'] = false;
      this.showRegexesListView(doc_type);
    },
    resetDocTypeRegexData() {
      this.doc_type_regexes = {} as dynamicObj;
      for (const doc_type in this.apiData) {
        const doc = this.apiData[doc_type];
        const name = doc.document_name;
        this.doc_type_regexes[name] = {} as dynamicObj;
        this.doc_type_regexes[name]['regexes'] = {
          data: [],
          display_list: false,
          api_data: false,
          loading_data: false,
        } as dynamicObj;
      }
    },
    async fetchLanguageOptions() {
      let response: any;
      let token: string = await getAuthorizationToken();
      response = await axios.get(
        addOrgIdQueryString(api.get_items_from_dictionary + 'DOC_ORIGIN'),
        {
          headers: {
            Authorization: token,
          },
        },
      );

      if (!response.data || Object.keys(response.data).length === 0) {
        throw { message: 'No language origin list found' };
      }

      this.language_origin_list = [];
      for (const prop in response.data) {
        let option = response.data[prop] as dynamicObj;
        this.language_origin_list.push(
          Object.assign(
            {},
            {
              value: option.value,
              label: option.label,
            },
          ),
        );
      }
    },

    async deleteDocumentType(row: any) {
      let response: any;
      try {
        if (isDefaultOrg(row.org_id)) {
          notify.error('Standard document cannot be deleted');
          return;
        }

        this.showLoading();
        let token: string = await getAuthorizationToken();
        response = await axios.delete(
          addOrgIdQueryString(api.delete_document_type + row.id),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === false) {
          throw response;
        }

        delete this.apiData[row.document_key];
        this.deleting_row = {} as dynamicObj;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async handleVisibilty(value: boolean, row: any) {
      let response: any;
      try {
        this.showLoading();
        let token: string = await getAuthorizationToken();

        let formData = new FormData();
        formData.append('id', row.id);
        formData.append('activate', value.toString());
        formData.append('org_id', getOrgId());

        response = await axios.post(
          api.activate_deactivate_document_type,
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === true) {
          await this.getDocTypesSubTypes();
          notify.success(response.data.message);
        } else {
          throw response;
        }
        this.apiData[row.document_key]['is_active'] = value;
      } catch (err) {
        this.apiData[row.document_key]['is_active'] = !value;
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async handleExtractionType(value: boolean, row: any) {
      let response: any;
      try {
        this.showLoading();
        let token: string = await getAuthorizationToken();

        let formData = new FormData();
        formData.append('id', row.id);
        formData.append(
          'extraction_type',
          value ? 'FLEX_COORDINATES' : 'FIX_COORDINATES',
        );
        formData.append('org_id', getOrgId());

        response = await axios.post(api.set_extraction_type, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === true) {
          notify.success(response.data.message);
        } else {
          throw response;
        }
        // this.apiData[row.document_key]['extraction_type_model'] = value;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    handleAutoAccountingSetting(value: boolean, row: any) {
      logInfo(this.doc_type_auto_accounting_setting, value);
    },
  },
  setup() {
    let data: any = [];
    const dropdown_store = useDropdownStore();
    const { getDocTypesSubTypes } = dropdown_store;
    const { doc_type_list } = storeToRefs(dropdown_store);

    let model = {} as { [k: string]: any };

    const form_builder_store = useFormBuilderStore();
    const { getTemplatesForDocuments } = form_builder_store;

    const settings_store = useSettingStore();
    const { getSetting, startSettingsFetch } = settings_store;
    const { user_settings, loading_settings, next_model_training_time } = storeToRefs(settings_store);

    const doc_attribute_store = useDocAttributesStore();
    const { getDocTypeAllSettings, getSettingsByDocTypeAndSettingKey } = doc_attribute_store;

    return {
      user_settings,
      next_model_training_time,
      doc_type_list,
      getSetting,
      startSettingsFetch,
      getDocTypesSubTypes,
      getTemplatesForDocuments,
      getDocTypeAllSettings,
      getSettingsByDocTypeAndSettingKey,
      apiData: ref(model),
      loading_doc_type_regex_data: ref(true),
      doc_type_regexes: ref(model),
      language_origin_list: data,
      deleteConfirm: ref(false),
      deleting_row: ref({} as dynamicObj),
      doc_type_auto_accounting_setting: ref({} as dynamicObj),
      currentDocType: ref(''),
      LAYOUT_BUILDER_MODULE: ref(true),
      options: [
        {
          label: 'Yes',
          value: 'true',
        },
        {
          label: 'No',
          value: 'false',
        },
      ],
    };
  },
});
</script>

