function CountdownTracker(label, value) {
  const el = document.createElement('span');

  el.className = 'flip-clock__piece';

  el.innerHTML =
    '<b class="flip-clock__card card"><b class="card__top"></b><b class="card__bottom"></b><b class="card__back"><b class="card__bottom"></b></b></b>';
  el.innerHTML += '<span class="flip-clock__dot"></span>';
  //hide text el.innerHTML += '<span class="flip-clock__slot">' + label + '</span>';

  this.el = el;

  const top = el.querySelector('.card__top');
  const bottom = el.querySelector('.card__bottom');
  const back = el.querySelector('.card__back');
  const backBottom = el.querySelector('.card__back .card__bottom');

  this.update = function (val) {
    const valStr = ('0' + val).slice(-2);
    if (valStr !== this.currentValue) {
      if (this.currentValue !== undefined && Number(this.currentValue) >= 0) {
        back.setAttribute('data-value', this.currentValue);
        bottom.setAttribute('data-value', this.currentValue);
      }
      this.currentValue = valStr;
      top.innerText = this.currentValue;
      backBottom.setAttribute('data-value', this.currentValue);

      this.el.classList.remove('flip');
      void this.el.offsetWidth;
      this.el.classList.add('flip');
    }
  };

  this.update(value);
}

// Calculation adapted from https://www.sitepoint.com/build-javascript-countdown-timer-no-dependencies/

function getTimeRemaining(endtime) {
  const t = Date.parse(endtime.toString()) - Date.parse(new Date().toString());
  return {
    Total: t,
    //'Days': Math.floor(t / (1000 * 60 * 60 * 24)),
    Hours: Math.floor((t / (1000 * 60 * 60)) % 24),
    Minutes: Math.floor((t / 1000 / 60) % 60),
    Seconds: Math.floor((t / 1000) % 60),
  };
}

function getTime() {
  const t = new Date();
  return {
    Total: t.getTime(),
    Hours: t.getHours() % 12,
    Minutes: t.getMinutes(),
    Seconds: t.getSeconds(),
  };
}

function getZeroTime() {
  return {
    Total: 0,
    Hours: 0,
    Minutes: 0,
    Seconds: 0,
  };
}

function getDistance(time) {
  const now = new Date().getTime();
  // Find the distance between now and the count down date
  const distance = time - now;
  return distance;
}

export default function Clock(countdown, callback) {
  const countdownDate = countdown
    ? new Date(Date.parse(countdown.toString()))
    : false;
  const callbackFn =
    callback ||
    function () {
      // function is empty
    };

  const updateFn = countdownDate ? getTimeRemaining : getTime;

  this.el = document.createElement('div');
  this.el.className = 'flip-clock';

  const trackers = {};
  const t = updateFn(countdownDate || new Date());
  let key;
  let timeinterval;

  for (key in t) {
    if (t[key] < 0) {
      t[key] = 0;
    } // dont show time in minus
    if (key === 'Total') {
      continue;
    }
    trackers[key] = new CountdownTracker(key, t[key]);
    this.el.appendChild(trackers[key].el);
  }

  let i = 0;
  const updateClock = () => {
    timeinterval = requestAnimationFrame(updateClock);

    // throttle so it's not constantly updating the time.
    if (i++ % 10) {
      return;
    }

    const t = updateFn(countdownDate || new Date());
    if (t.Total < 0) {
      cancelAnimationFrame(timeinterval);
      for (key in trackers) {
        trackers[key].update(0);
      }
      callbackFn();
      return;
    }

    for (key in trackers) {
      trackers[key].update(t[key]);
    }
  };

  setTimeout(updateClock, 500);
}
